  const g = {};
  for (const en of e.entries){ (g[en.evidence_id] ??= []).push(en.source_id); }
  console.log("=====", c.id, "query order:", JSON.stringify(c.query_ids));
  for (const q of c.query_ids){ console.log(q, JSON.stringify([...new Set(g[q]||[])])); }
  if (Object.keys(g).length !== c.query_ids.length) console.log("other evidence ids:", Object.keys(g).filter(k=>!c.query_ids.includes(k)));
  out.push({id:c.id, recorded_origin_count:e.recorded_origin_count, query_ids:c.query_ids, g});
}
return out;

const ids = ["G01","G02","G03","G04","G05","G06"];
const results = await Promise.all(ids.map(id => tools.origin_packet({case_id: id})));
const cases = results.map((p) => {
  const c = p.cases[0];
  const e = c.evidence;
  const g = new Map();
  for (const en of e.entries){
    if (!g.has(en.evidence_id)) g.set(en.evidence_id, []);
    g.get(en.evidence_id).push(en.source_id);
  }
  return {
    id: c.id,
    recorded_origin_count: e.recorded_origin_count,
    independence: "unknown",
    queries: c.query_ids.map(q => ({ material_id: q, origins: [...new Set(g.get(q) || [])] }))
  };
});
console.log(JSON.stringify({cases}));
